import review_remaining605 as r
b=r.folder(38);ids=[x['id'] for x in r.read(b/'related295-source.json')]
rows=[(1,'PM2.5에는지름1인A만있어A질량20이고PM10에는A와B모두있어B질량100-20=80이다.따라서전체질량A:B=1:4이다.밀도가같은구이고지름비1:4이므로개당질량1:64이다.개수a:b=(20/1):(80/64)=16:1로①다.PM10을B만의농도로읽거나질량비를개수비로오인하면틀린다.같은지역동일공기부피의농도비를쓰므로부피기준이상쇄된다.', ['A질량20/B질량80과개당질량1대64를나누면개수16대1이다.','8대1은지름세제곱64와질량비1대4의몫16을재현하지못한다.','4대1은전체질량비를뒤집은것일뿐개당질량64배를반영하지못한다.','1대4는A와B의전체질량비이며묻는개수비와다르다.','1대8은PM2.5의A질량20및B질량80과개당질량비에맞지않는다.']),
(5,'A복권일시금은1등당첨금의60%를받고거기서세금도공제하므로원래1등당첨금보다적어⑤맞다.공공기금은25%로과반아니며1890년대금지후20세기초합법복권은거의사라졌다.1등미배출이월은판매액전부가아닌배정당첨금이며메가밀리언즈45개주를모든주로확대못한다.본문수치와시대서술만사용하며현재미국정책이나실제복권세율을외삽하지않는다.', ['공공기금비중25%는과반50%초과가아니므로틀리다.','금지이후20세기초합법복권은확산된것이아니라거의사라졌다고한다.','이월되는것은배정된1등당첨금으로판매액전부라는범위가아니다.','45개주에서판매된다고하므로미국모든주라는전칭진술은맞지않는다.','일시금은원당첨금의60%이며세금공제까지적용되어원당첨금보다적다.']),
(1,'표에서외부참여가능성높은유형C이고마지막문단관료제영향력작고통제약한분야에서작동한다는①과일치한다.상호의존성보통B에A의폐쇄성을옮긴②틀림.합의효율성높은A보다B가더효과적일수있으므로효율최고를목표달성최고로확대하는③틀림.A/B이익집단별영향력대소는제시없고C참여자증가가합의를어렵게할뿐지속성증가라는⑤근거없다.', ['표외부참여높음은C이고본문이관료제영향력작고통제약한분야라고설명한다.','상호의존성보통은B이며다른집단을철저히배제하는것은A이다.','합의효율성높음A라도B가더효과적으로목표를달성할수있어최고효과를단정못한다.','A와B전체특성비교에서개별이익집단의정책영향력대소는도출되지않는다.','C참여자가많으면합의가어렵다고하며지속성이높아진다는상관관계는제시되지않는다.'])]
assert not (b/'related295-own-solves.json').exists();r.write(b/'related295-own-solves.json',[dict(id=i,answer=a,reasoning=s,optionReasons=o) for i,(a,s,o) in zip(ids,rows)])
r.write(b/'related295-solve-frozen.json',dict(frozenAt=r.now(),sha256=r.sha(b/'related295-own-solves.json'),beforeReveal=True))
